import { Button, Group, Stack, Text } from "@mantine/core";
import { useWidgetClock, useWidgetCommands, useWidgetHost, useWidgetOptions, useWidgetState } from "@homarr/widget-sdk";

export default function Clock() {
  const now = useWidgetClock();
  const host = useWidgetHost();
  const options = useWidgetOptions<{title:string}>();
  const [showSeconds, setShowSeconds] = useWidgetState("showSeconds", true);
  useWidgetCommands([{ id: "seconds", label: "Toggle seconds", run: () => setShowSeconds((value) => !value) }]);
  const zones = [host.timeZone, "UTC", "America/New_York", "Asia/Tokyo"];
  const time = (zone:string) => {
    if (now === null) return "—";
    return new Intl.DateTimeFormat(host.locale, { timeZone: zone, hour: "2-digit", minute: "2-digit", ...(showSeconds ? { second: "2-digit" } : {}) }).format(now);
  };
  return <Stack h="100%" justify="center" gap="sm" p="md">
    <Text size="sm" c="dimmed">{options.title}</Text>
    <Text size={host.displayMode === "advanced" ? "3rem" : "2rem"} fw={700}>{time(host.timeZone)}</Text>
    {host.displayMode === "advanced" && zones.filter((zone, index) => zones.indexOf(zone) === index).map((zone) =>
      <Group key={zone} justify="space-between"><Text>{zone}</Text><Text ff="monospace">{time(zone)}</Text></Group>
    )}
    <Button size="compact-xs" variant="subtle" onClick={() => setShowSeconds((value) => !value)}>Toggle seconds</Button>
  </Stack>;
}
